import{_ as s,o as i,c as e,a3 as t}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"对SpringCloud Gateway的支持","description":"响应式 Spring Cloud Gateway 的 TLog GlobalFilter、转发子 span 和响应头开关。","frontmatter":{"title":"对SpringCloud Gateway的支持","date":"2022-09-12T15:46:33.000Z","permalink":"/pages/48265b/","description":"响应式 Spring Cloud Gateway 的 TLog GlobalFilter、转发子 span 和响应头开关。"},"headers":[],"relativePath":"pages/48265b/index.md","filePath":"10.文档/200.对SpringCloud Gateway的支持.md"}'),n={name:"pages/48265b/index.md"};function l(p,a,h,r,d,o){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="对springcloud-gateway的支持" tabindex="-1">对SpringCloud Gateway的支持 <a class="header-anchor" href="#对springcloud-gateway的支持" aria-label="Permalink to &quot;对SpringCloud Gateway的支持&quot;">​</a></h1><p>在响应式 Spring Cloud Gateway 服务中引入 <code>tlog-gateway-spring-boot-starter:2.0.0</code>，TLog 会注册自己的 <code>GlobalFilter</code>。不需要为了网关再叠加 <code>tlog-web-spring-boot-starter</code> 或手工创建 TLog Filter。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;com.yomahub&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;tlog-gateway-spring-boot-starter&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>应用仍需自己声明与 Boot 版本匹配的 Spring Cloud Gateway 依赖。TLog 只支持基于 WebFlux 的 Spring Cloud Gateway，不支持 Spring Cloud Gateway Server MVC。</p><h2 id="上下文与下游调用" tabindex="-1">上下文与下游调用 <a class="header-anchor" href="#上下文与下游调用" aria-label="Permalink to &quot;上下文与下游调用&quot;">​</a></h2><p>网关在入口建立或沿用 traceId，为转发请求写入子 span。后续 WebFlux 服务再通过 WebClient 调用下游时，典型链路为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gateway                 WebFlux                  HTTP 下游</span></span>
<span class="line"><span>trace = 同一个值        trace = 同一个值         trace = 同一个值</span></span>
<span class="line"><span>span  = 0               span  = 0.1              span  = 0.1.1</span></span></code></pre></div><p>普通 WebFlux 服务不会为了建立入口上下文而改写收到的请求头；网关的实际转发才会注入子 span。无需在路由代码里手工拷贝 TLog 头。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tlog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    response-header</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>总开关、Web 开关和响应头回写开关都适用于 Gateway。应用名可选，未配置 <code>spring.application.name</code> 时使用 <code>NONE</code>。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>示例工程 <code>tlog-example-gateway</code> 演示 Gateway → WebFlux → HTTP 三进程链路，运行方法见<a href="/guide/examples/#webflux、gateway-与-dubbo">可运行示例</a>。</p><p>响应式上下文依赖 Reactor Context 和 TLog 的 operator hook，外部原生线程等边界见<a href="/guide/webflux/">WebFlux 说明</a>。</p>`,13)])])}const E=s(n,[["render",l]]);export{g as __pageData,E as default};
